 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    # The five-cell horizontal pattern is the template to stamp at each marker.
    template = None
    for r, row in enumerate(g):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if c - start == 5:
                template = row[start:c]
                break
        if template is not None:
            break
    if template is None:
        return g

    # Markers are the isolated non-background cells not belonging to the template.
    markers = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == bg and False:
                continue
            if g[r][c] != bg:
                # Ignore the source object and other components; isolated singleton only.
                if all(not (0 <= r + dr < h and 0 <= c + dc < w and
                            g[r + dr][c + dc] != bg)
                       for dr, dc in ((-1,0),(1,0),(0,-1),(0,1))):
                    markers.append((r, c))

    # Source object is a contiguous horizontal component; singleton markers are replaced
    # by a copy of the template centered on their original cell.
    for r, c in markers:
        left = c - len(template) // 2
        for i, color in enumerate(template):
            x = left + i
            if 0 <= x < w:
                g[r][x] = color
    return g
